INSERT INTO trucker.date_dim_ch
  (id, date_id, d_date, month_seq, week_seq, quarter_seq, d_year, dow, moy,
   dom, qoy, fy_year, fy_quarter_seq, fy_week_seq, day_name, quarter_name,
   holiday, weekend, following_holiday, first_dom, last_dom, same_day_ly,
   same_day_lq, current_day, current_week, current_month, current_quarter,
   current_year, deleted)
SELECT r.id,
       argMaxState(r.date_id,            now64()),
       argMaxState(r.d_date,             now64()),
       argMaxState(r.month_seq::Int32,   now64()),
       argMaxState(r.week_seq::Int32,    now64()),
       argMaxState(r.quarter_seq::Int32, now64()),
       argMaxState(r.d_year::Int32,      now64()),
       argMaxState(r.dow::Int32,         now64()),
       argMaxState(r.moy::Int32,         now64()),
       argMaxState(r.dom::Int32,         now64()),
       argMaxState(r.qoy::Int32,         now64()),
       argMaxState(r.fy_year::Int32,     now64()),
       argMaxState(r.fy_quarter_seq::Int32, now64()),
       argMaxState(r.fy_week_seq::Int32, now64()),
       argMaxState(r.day_name,           now64()),
       argMaxState(r.quarter_name,       now64()),
       argMaxState(r.holiday,            now64()),
       argMaxState(r.weekend,            now64()),
       argMaxState(r.following_holiday,  now64()),
       argMaxState(r.first_dom::Int32,   now64()),
       argMaxState(r.last_dom::Int32,    now64()),
       argMaxState(r.same_day_ly::Int32, now64()),
       argMaxState(r.same_day_lq::Int32, now64()),
       argMaxState(r.current_day,        now64()),
       argMaxState(r.current_week,       now64()),
       argMaxState(r.current_month,      now64()),
       argMaxState(r.current_quarter,    now64()),
       argMaxState(r.current_year,       now64()),
       argMaxState({{ .operation | eq "delete" }}, now64())
FROM {{ .rows }}
GROUP BY id
